\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\pagestyle{empty}

% ── Lancet-style Slate Color Theme ──
\definecolor{primary}{HTML}{1E3A5F}      % deep navy
\definecolor{secondary}{HTML}{2D5F8A}    % medium slate blue
\definecolor{accent}{HTML}{0D9488}        % clinical teal
\definecolor{gold}{HTML}{B8860B}          % muted gold for warnings
\definecolor{bgposter}{HTML}{F0F4F8}     % cool slate background
\definecolor{redbg}{HTML}{FFF5F5}        % warm red tint
\definecolor{bluebg}{HTML}{F0F7FF}       % cool blue tint
\definecolor{tealbg}{HTML}{F0FFFE}       % teal tint
\definecolor{cream}{HTML}{FDF8F3}        % warm cream
\definecolor{textdark}{HTML}{1E293B}
\definecolor{textgray}{HTML}{475569}
\definecolor{stathighlight}{HTML}{E0F2FE}
\definecolor{warningbg}{HTML}{FEF3C7}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=20pt, itemsep=5pt, parsep=2pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{24}{30}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe design) ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=bluebg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=bluebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=tealbg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.15},
  },
  redcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=redbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=redbg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!40},
    valign=top, drop shadow={opacity=0.15},
  },
  goldcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=warningbg,
    borderline west={5pt}{0pt}{gold},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{gold},
    coltitle=gold, colbacktitle=warningbg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={gold!40},
    valign=top, drop shadow={opacity=0.15},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!20!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=12pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.2},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ════════════════════════════════════════════════════════════
% TITLE BAR (span=3)
% ════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=white,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.3}
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{72}{86}\selectfont\bfseries Artificial Intelligence in Clinical Decision-Making}\\[10pt]
  {\fontsize{32}{40}\selectfont Performance, Safety, and Implementation Gaps}\\[8pt]
  {\fontsize{26}{34}\selectfont\color{white!80} The Lancet Digital Health -- AI in Clinical Medicine Symposium}
}

% ════════════════════════════════════════════════════════════
% STATS BANNER (anchor stats, span=3)
% ════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=primary!8!white, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{primary!30},
]{name=stats, column=1, span=3, between=row4 and row7}{
  \centering
  \begin{tabular}[c]{@{}c@{}c@{}c@{}}
    % Stat 1: Anchor stat - <5%
    \fcolorbox{primary!50}{stathighlight}{\parbox{0.28\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{primary}\textless 5\%}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Prospective Validation Rate}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textgray} of published AI models}\vspace{8pt}%
    }} &
    % Stat 2: Sensitivity comparison
    \fcolorbox{accent!50}{tealbg}{\parbox{0.28\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{56}{68}\selectfont\bfseries\color{accent}87.5\%}\\[2pt]
      {\fontsize{20}{26}\selectfont\color{textdark} AI vs 78.2\% Clinician}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textgray} Median Diagnostic Sensitivity}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{accent} +9.3pp advantage}\vspace{8pt}%
    }} &
    % Stat 3: Bias assessment warning
    \fcolorbox{gold!50}{warningbg}{\parbox{0.28\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{64}{78}\selectfont\bfseries\color{gold}18\%}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textdark} Studies Reporting}\\[2pt]
      {\fontsize{18}{24}\selectfont\color{textgray} Demographic Bias Assessment}\\[2pt]
      {\fontsize{16}{20}\selectfont\color{gold} Safety \& Equity Gap}\vspace{8pt}%
    }}
  \end{tabular}
}

% ════════════════════════════════════════════════════════════
% ROW A: Background & Motivation (col1) | Diagnostic Performance (col2) | Safety & Bias (col3)
% ════════════════════════════════════════════════════════════

% ── Background & Motivation ──
\posterbox[redcard, title={Background \& Motivation}
]{name=bg, column=1, between=row7 and row12}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item AI-CDSS rapidly expanding in digital health
    \item 400+ studies in systematic review evidence base
    \item Translation to routine clinical practice remains limited
  \end{itemize}
  \vspace{4pt}
  \colorbox{primary!15}{\parbox{0.92\linewidth}{%
    \centering\vspace{4pt}%
    {\fontsize{22}{28}\selectfont\color{primary}\bfseries Key Question:}\\[4pt]
    {\fontsize{18}{24}\selectfont\color{textdark} Why do promising AI tools fail to reach bedside deployment?}
    \vspace{4pt}%
  }}
}

% ── Diagnostic Performance (with domain table) ──
\posterbox[tealcard, title={Diagnostic Performance}
]{name=diag, column=2, between=row7 and row12}{
  \fontsize{28}{36}\selectfont
  \textbf{Across 400+ Studies:}\\[4pt]
  \begin{tabular}[t]{l|c|c}
    \rowcolor{accent!15}
    \textbf{Domain} & \textbf{AI Sens.} & \textbf{Clinician} \\ \hline
    Radiology & 89.3\% & 79.8\% \\
    Dermatology & 86.7\% & 76.5\% \\
    Ophthalmology & 90.1\% & 82.3\% \\
    Pathology & 84.0\% & 74.1\%
  \end{tabular}\\[6pt]
  \colorbox{accent!18}{\parbox{0.92\linewidth}{%
    \fontsize{20}{26}\selectfont\color{accent}\bfseries 32\% faster}\\[2pt]
    \fontsize{16}{22}\selectfont\color{textdark} Diagnostic turnaround time with AI assistance
  }}
}

% ── Safety, Bias & Health Equity ──
\posterbox[goldcard, title={Safety, Bias \& Health Equity}
]{name=safety, column=3, between=row7 and row12}{
  \fontsize{30}{40}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item Only 18\% of studies assessed demographic bias
    \item 5--12pp sensitivity gap for underrepresented groups
    \item Dermatologi AI: trained mainly on lighter skin tones
    \item \textless 1\% adverse events in prospective trials (likely under-reported)
  \end{itemize}
  \vspace{4pt}
  \colorbox{gold!20}{\parbox{0.92\linewidth}{%
    \fontsize{18}{24}\selectfont\color{gold}\bfseries No standardised safety-reporting frameworks for AI-CDSS}
  }}
}

% ════════════════════════════════════════════════════════════
% ROW B: Implementation Gap (col1-2) | FDA Devices (col3)
% ════════════════════════════════════════════════════════════

% ── The Translational Implementation Gap ──
\posterbox[navycard, title={The Translational Implementation Gap}
]{name=gap, column=1, span=2, between=row12 and row16}{
  \fontsize{30}{40}\selectfont
  \begin{minipage}{0.46\linewidth}
    \centering
    \fcolorbox{primary!40}{stathighlight}{\parbox{0.9\linewidth}{%
      \centering\vspace{6pt}%
      {\fontsize{48}{58}\selectfont\bfseries\color{primary}\textless 5\%}\\[4pt]
      {\fontsize{20}{26}\selectfont\color{textdark} of AI models reach prospective clinical validation}
      \vspace{6pt}%
    }}
  \end{minipage}
  \hfill
  \begin{minipage}{0.50\linewidth}
    \textbf{Key Barriers:}\\[6pt]
    \begin{itemize}
      \item Fragmented EHR systems, poor interoperability
      \item Regulatory frameworks lag AI development pace
      \item Insufficient explainability undermines clinician trust
      \item Limited cost-effectiveness evidence for health systems
      \item Poor alignment with existing clinical workflows
    \end{itemize}
  \end{minipage}
}

% ── FDA Cleared Devices ──
\posterbox[tealcard, title={Regulatory Landscape (FDA)}
]{name=regulatory, column=3, between=row12 and row16}{
  \centering
  \fcolorbox{accent!40}{tealbg}{\parbox{0.88\linewidth}{%
    \centering\vspace{8pt}%
    {\fontsize{56}{68}\selectfont\bfseries\color{accent}692}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textdark} AI/ML-Enabled Medical Devices}\\[2pt]
    {\fontsize{18}{24}\selectfont\color{textgray} Cleared by FDA (as of 2023)}\\[2pt]
    {\fontsize{16}{20}\selectfont\color{accent} vs. \textless 5\% prospective validation}
    \vspace{8pt}%
  }}
}

% ════════════════════════════════════════════════════════════
% ROW C: Recommendations (full width)
% ════════════════════════════════════════════════════════════
\posterbox[highlightcard, title={Recommendations \& Future Directions}
]{name=recs, column=1, span=3, between=row16 and row20}{
  \fontsize{30}{40}\selectfont
  \begin{tabular}[c]{@{}c@{}c@{}c@{}c@{}c@{}}
    \parbox{0.18\linewidth}{\centering
      \colorbox{primary!20}{\parbox{0.92\linewidth}{%
        \centering\vspace{4pt}%
        {\fontsize{20}{26}\selectfont\color{primary}\bfseries 1}\\[2pt]
        {\fontsize{16}{22}\selectfont\color{textdark} Mandate prospective validation}
        \vspace{4pt}%
      }}
    } &
    \parbox{0.18\linewidth}{\centering
      \colorbox{accent!20}{\parbox{0.92\linewidth}{%
        \centering\vspace{4pt}%
        {\fontsize{20}{26}\selectfont\color{accent}\bfseries 2}\\[2pt]
        {\fontsize{16}{22}\selectfont\color{textdark} Standardise bias auditing}
        \vspace{4pt}%
      }}
    } &
    \parbox{0.18\linewidth}{\centering
      \colorbox{secondary!20}{\parbox{0.92\linewidth}{%
        \centering\vspace{4pt}%
        {\fontsize{20}{26}\selectfont\color{secondary}\bfseries 3}\\[2pt]
        {\fontsize{16}{22}\selectfont\color{textdark} Shared safety-reporting registries}
        \vspace{4pt}%
      }}
    } &
    \parbox{0.18\linewidth}{\centering
      \colorbox{gold!20}{\parbox{0.92\linewidth}{%
        \centering\vspace{4pt}%
        {\fontsize{20}{26}\selectfont\color{gold}\bfseries 4}\\[2pt]
        {\fontsize{16}{22}\selectfont\color{textdark} Invest in interoperability (FHIR/OMOP)}
        \vspace{4pt}%
      }}
    } &
    \parbox{0.18\linewidth}{\centering
      \colorbox{primary!20}{\parbox{0.92\linewidth}{%
        \centering\vspace{4pt}%
        {\fontsize{20}{26}\selectfont\color{primary}\bfseries 5}\\[2pt]
        {\fontsize{16}{22}\selectfont\color{textdark} Prioritise explainability research}
        \vspace{4pt}%
      }}
    }
  \end{tabular}
}

\end{tcbposter}
\end{document}

